// Two scopes (Azure OpenAI Responses API, web_search tool):
//   verified — AUTHORITATIVE sites only (the allow-list below, max 20 domains)
//   open     — the wider web, for useful information not on the list (industry/manufacturer guidance, research,
//              practice articles). Every source is tagged verified/unverified afterwards, so answers can label it.
// The documents stay the source of truth either way.
const ALLOWED_DOMAINS = ["epa.gov", "ecfr.gov", "federalregister.gov", "fema.gov", "usace.army.mil", "nrcs.usda.gov", "fhwa.dot.gov", "usgs.gov", "noaa.gov"];  // add your state environmental agency, state regulations site and local public-works domains
const LOCATION = { type: 'approximate', country: 'US' };  // optionally add region: '<your state>'
const query = String($json.query ?? '').trim();
const scope = String($json.scope ?? 'verified').toLowerCase() === 'open' ? 'open' : 'verified';
const tool = { type: 'web_search', user_location: LOCATION };
if (scope === 'verified') tool.filters = { allowed_domains: ALLOWED_DOMAINS };
return [{ json: { query, scope, allowed: ALLOWED_DOMAINS, body: {
  model: 'gpt-5.4-mini',
  reasoning: { effort: 'low' },
  max_output_tokens: 2500,
  instructions: 'You research current regulations, standards, technologies and best practices for engineering staff. ' +
    'Use only what the web search returns. Be concise (at most 250 words): key points as bullets, each with its source ' +
    'and publisher and, where the source shows it, its date. Put every point in its own bullet with its own source link. ' +
    (scope === 'open' ? 'Prefer reputable sources (government, standards bodies, universities, professional associations, manufacturers\' technical documents) and say what kind of source each is. Do not use or cite these domains — they are searched separately: ' + ALLOWED_DOMAINS.join(', ') + '. ' : '') +
    'If sources disagree or nothing credible is found, say so plainly.',
  input: query,
  tools: [tool],
} } }];

// Hand the agent the findings ALREADY SORTED by trust level, bullet by bullet, from each bullet's cited link(s):
// every link allow-listed → verified_findings; any other link, or no link → wider_findings. The agent only has to put
// each list under its heading, so a verified source can never end up labelled "wider web" (or the reverse).
const r = $json;
const req = $('Build web search request').first().json;
const today = new Date().toISOString().slice(0, 10);
if (r.error || !Array.isArray(r.output)) {
  const msg = r.error?.message ?? r.error ?? 'no response';
  return [{ json: { scope: req.scope, verified_findings: '', wider_findings: '', note: `Web search failed: ${String(msg).slice(0, 200)}`, retrieved: today } }];
}
// (no URL() in the Code-node sandbox — take the host with a pattern)
const verifiedHost = url => { const h = (String(url).match(/^https?:\/\/([^\/?#:]+)/i)?.[1] ?? '').toLowerCase();
  return !!h && req.allowed.some(d => h === d || h.endsWith('.' + d)); };
let text = '';
for (const o of r.output) for (const c of o.content ?? []) if (c.type === 'output_text') text += c.text + '\n\n';
const verified = [], wider = [];
for (const block of text.split(/\n\s*\n|\n(?=\s*(?:[-*•]|\d+\.)\s)/).map(s => s.trim()).filter(Boolean)) {
  const urls = [...block.matchAll(/\]\((https?:\/\/[^)\s]+)\)/g)].map(m => m[1]);
  const isBullet = /^(?:[-*•]|\d+\.)\s/.test(block);
  if (!urls.length && !isBullet) continue;                     // intro / heading lines without a source
  (urls.length && urls.every(verifiedHost) ? verified : wider).push(block);
}
return [{ json: {
  scope: req.scope,
  verified_findings: verified.join('\n\n') || '(none)',
  wider_findings: req.scope === 'open' ? (wider.join('\n\n') || '(none)') : '(not searched)',
  retrieved: today,
  note: 'verified_findings go under "From verified public sources"; wider_findings go under "From the wider web — not on the verified list".',
} }];
